SET @srm5_item_unique := (SELECT COUNT(*) FROM (SELECT index_name,GROUP_CONCAT(column_name ORDER BY seq_in_index) cols FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='student_registration_modification_items' AND non_unique=0 AND index_name<>'PRIMARY' GROUP BY index_name) i WHERE (index_name='uq_srmodi_offering' AND cols='student_registration_modification_request_id,course_offering_id') OR (index_name='uq_srmodi_source' AND cols='student_registration_modification_request_id,source_student_course_registration_id'));
SET @srm5_request_fks := (SELECT COUNT(*) FROM information_schema.referential_constraints WHERE constraint_schema='alrowad_uni_rust' AND table_name='student_registration_modification_requests' AND constraint_name IN ('fk_srmod_initial','fk_srmod_student','fk_srmod_year','fk_srmod_semester','fk_srmod_advisor') AND update_rule='RESTRICT' AND delete_rule='RESTRICT');
SET @srm5_item_fks := (SELECT COUNT(*) FROM information_schema.referential_constraints WHERE constraint_schema='alrowad_uni_rust' AND table_name='student_registration_modification_items' AND constraint_name IN ('fk_srmodi_request','fk_srmodi_offering','fk_srmodi_source_registration','fk_srmodi_materialized_registration') AND update_rule='RESTRICT' AND delete_rule='RESTRICT');
SET @srm5_event_fks := (SELECT COUNT(*) FROM information_schema.referential_constraints WHERE constraint_schema='alrowad_uni_rust' AND table_name='student_registration_modification_events' AND constraint_name IN ('fk_srmode_request','fk_srmode_actor') AND update_rule='RESTRICT' AND delete_rule='RESTRICT');
SET @srm5_request_fk_links := (SELECT COUNT(*) FROM information_schema.key_column_usage WHERE constraint_schema='alrowad_uni_rust' AND table_name='student_registration_modification_requests' AND ((column_name='initial_registration_request_id' AND referenced_table_name='student_registration_requests' AND referenced_column_name='student_registration_request_id') OR (column_name='student_id' AND referenced_table_name='students' AND referenced_column_name='student_id') OR (column_name='academic_year_id' AND referenced_table_name='academic_years' AND referenced_column_name='academic_year_id') OR (column_name='semester_id' AND referenced_table_name='semesters' AND referenced_column_name='semester_id') OR (column_name='advisor_user_id' AND referenced_table_name='users' AND referenced_column_name='user_id')));
SET @srm5_item_fk_links := (SELECT COUNT(*) FROM information_schema.key_column_usage WHERE constraint_schema='alrowad_uni_rust' AND table_name='student_registration_modification_items' AND ((column_name='student_registration_modification_request_id' AND referenced_table_name='student_registration_modification_requests' AND referenced_column_name='student_registration_modification_request_id') OR (column_name='course_offering_id' AND referenced_table_name='course_offerings' AND referenced_column_name='course_offering_id') OR (column_name='source_student_course_registration_id' AND referenced_table_name='student_course_registrations' AND referenced_column_name='student_course_registration_id') OR (column_name='materialized_student_course_registration_id' AND referenced_table_name='student_course_registrations' AND referenced_column_name='student_course_registration_id')));
SET @srm5_event_fk_links := (SELECT COUNT(*) FROM information_schema.key_column_usage WHERE constraint_schema='alrowad_uni_rust' AND table_name='student_registration_modification_events' AND ((column_name='student_registration_modification_request_id' AND referenced_table_name='student_registration_modification_requests' AND referenced_column_name='student_registration_modification_request_id') OR (column_name='actor_user_id' AND referenced_table_name='users' AND referenced_column_name='user_id')));
SET @srm5_request_checks := (SELECT COUNT(*) FROM information_schema.table_constraints WHERE constraint_schema='alrowad_uni_rust' AND table_name='student_registration_modification_requests' AND constraint_name IN ('chk_srmod_status','chk_srmod_version','chk_srmod_current','chk_srmod_submission','chk_srmod_return','chk_srmod_terminal','chk_srmod_materialized','chk_srmod_snapshot') AND constraint_type='CHECK');
SET @srm5_item_checks := (SELECT COUNT(*) FROM information_schema.table_constraints WHERE constraint_schema='alrowad_uni_rust' AND table_name='student_registration_modification_items' AND constraint_name IN ('chk_srmodi_operation','chk_srmodi_source') AND constraint_type='CHECK');
SET @srm5_event_checks := (SELECT COUNT(*) FROM information_schema.table_constraints WHERE constraint_schema='alrowad_uni_rust' AND table_name='student_registration_modification_events' AND constraint_name IN ('chk_srmode_type','chk_srmode_version') AND constraint_type='CHECK');
SET @srm5_request_indexes := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='student_registration_modification_requests' AND (index_name,seq_in_index,column_name) IN (('idx_srmod_queue',1,'status'),('idx_srmod_queue',2,'last_submitted_at'),('idx_srmod_queue',3,'student_registration_modification_request_id'),('idx_srmod_initial',1,'initial_registration_request_id'),('idx_srmod_advisor',1,'advisor_user_id')));
SET @srm5_item_indexes := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='student_registration_modification_items' AND (index_name,seq_in_index,column_name) IN (('idx_srmodi_materialized',1,'materialized_student_course_registration_id')));
SET @srm5_event_indexes := (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema='alrowad_uni_rust' AND table_name='student_registration_modification_events' AND (index_name,seq_in_index,column_name) IN (('idx_srmode_request_history',1,'student_registration_modification_request_id'),('idx_srmode_request_history',2,'created_at'),('idx_srmode_actor',1,'actor_user_id')));
SET @srm5_request_owned := (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='student_registration_modification_requests' AND engine='InnoDB' AND table_comment LIKE 'Owned by semester-registration-modifications-phase5%');
SET @srm5_item_owned := (SELECT COUNT(*) FROM information_schema.tables WHERE table_schema='alrowad_uni_rust' AND table_name='student_registration_modification_items' AND engine='InnoDB' AND table_comment LIKE 'Owned by semester-registration-modifications-phase5%');
