SET @srm5_request_compatible := (@srm5_request_exists=0 OR (@srm5_request_columns=26 AND @srm5_request_total_columns=26 AND @srm5_request_signed=6 AND @srm5_request_pk=1 AND @srm5_request_unique=1 AND @srm5_request_fks=5 AND @srm5_request_fk_links=5 AND @srm5_request_checks=8 AND @srm5_request_indexes=5 AND @srm5_request_owned=1));
SET @srm5_item_compatible := (@srm5_item_exists=0 OR (@srm5_item_columns=8 AND @srm5_item_total_columns=8 AND @srm5_item_signed=5 AND @srm5_item_pk=1 AND @srm5_item_unique=2 AND @srm5_item_fks=4 AND @srm5_item_fk_links=4 AND @srm5_item_checks=2 AND @srm5_item_indexes=1 AND @srm5_item_owned=1));
SET @srm5_event_compatible := (@srm5_event_exists=0 OR (@srm5_event_columns=9 AND @srm5_event_total_columns=9 AND @srm5_event_signed=3 AND @srm5_event_pk=1 AND @srm5_event_fks=2 AND @srm5_event_fk_links=2 AND @srm5_event_checks=2 AND @srm5_event_indexes=3 AND @srm5_event_owned=1));
SET @srm5_target_compatible := (@srm5_request_compatible AND @srm5_item_compatible AND @srm5_event_compatible);
SET @srm5_target_complete := (@srm5_target_tables=3 AND @srm5_target_compatible);
SET @srm5_ready := (@srm5_db=1 AND @srm5_core_tables=24 AND @srm5_phase2_columns=3 AND @srm5_phase4_columns=6 AND @srm5_signed_keys=7 AND @srm5_permissions=2 AND @srm5_advisor_mapping=2 AND @srm5_target_compatible);

SELECT 'DATABASE_AND_CORE' report_section,IF(@srm5_db=1 AND @srm5_core_tables=24,'PASS','FAIL') result,CONCAT('core_tables=',@srm5_core_tables,'/24') detail;
SELECT 'PHASE2_AND_PHASE4' report_section,IF(@srm5_phase2_columns=3 AND @srm5_phase4_columns=6,'PASS','FAIL') result,CONCAT('deadline_columns=',@srm5_phase2_columns,'/3; timetable_columns=',@srm5_phase4_columns,'/6') detail;
SELECT 'KEY_AND_ADVISOR_RBAC' report_section,IF(@srm5_signed_keys=7 AND @srm5_permissions=2 AND @srm5_advisor_mapping=2,'PASS','FAIL') result,CONCAT('signed_keys=',@srm5_signed_keys,'/7; permissions=',@srm5_permissions,'/2; advisor_mappings=',@srm5_advisor_mapping,'/2') detail;
SELECT 'PHASE5_OBJECTS' report_section,CASE WHEN NOT @srm5_target_compatible THEN 'CONFLICTING' WHEN @srm5_target_tables=0 THEN 'ABSENT' WHEN @srm5_target_complete THEN 'COMPATIBLE' ELSE 'INCOMPLETE_RESUMABLE' END result,CONCAT('tables=',@srm5_target_tables,'/3; requests=',IF(@srm5_request_exists=0,'MISSING',IF(@srm5_request_compatible,'COMPATIBLE','CONFLICTING')),'; items=',IF(@srm5_item_exists=0,'MISSING',IF(@srm5_item_compatible,'COMPATIBLE','CONFLICTING')),'; events=',IF(@srm5_event_exists=0,'MISSING',IF(@srm5_event_compatible,'COMPATIBLE','CONFLICTING'))) detail;
SELECT 'INFORMATIONAL' report_section,'INFO' result,(SELECT COUNT(*) FROM `alrowad_uni_rust`.`student_registration_requests` WHERE status='approved') approved_initial_requests,(SELECT COUNT(*) FROM `alrowad_uni_rust`.`student_course_registrations` scr JOIN `alrowad_uni_rust`.`registration_statuses` rs ON rs.registration_status_id=scr.registration_status_id WHERE rs.status_code='registered') current_registrations,(SELECT COUNT(*) FROM `alrowad_uni_rust`.`student_registration_withdrawal_requests` WHERE current_slot=1) current_withdrawals;
SELECT 'OVERALL' report_section,IF(@srm5_ready,'READY','BLOCKED') result;
